import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).parent))
from _page import PAGE, RESULT
import asyncio, json, sys
from playwright.async_api import async_playwright
URL=PAGE
R=[]
def rec(item, ok, detail=''): R.append({'item':item,'pass':bool(ok),'detail':detail}); print(('PASS' if ok else 'FAIL'), item, '|', str(detail)[:230])
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch(); ctx=await b.new_context(viewport={'width':1440,'height':900}, accept_downloads=True); pg=await ctx.new_page()
