        await as_('payments','refunds')
        await appr('RF-501')
        over=await pg.evaluate("()=>!document.querySelector('[data-rf-approve=\"RF-504\"]')")
        await pg.evaluate("()=>document.dispatchEvent(new Event('x'))")
        note=await pg.evaluate("()=>document.querySelector('[data-rf=\"RF-504\"]').innerText")
        rec('Payment approver approves within limit (with a confirmation); above-limit says who decides', (await st('RF-501')).startswith('Approved') and over and 'owner decides' in note, f"RF-501 {await st('RF-501')}; RF-504 → '{note.split(chr(9))[-1].strip()}'")
        await as_('manager','refunds'); await appr('RF-502'); t=await T()
        rec('Nobody approves a refund they requested', 'requested' in t and (await st('RF-502'))=='Pending', t)
        await pg.click('[data-rf-approve="RF-503"]') if await pg.locator('[data-rf-approve="RF-503"]').count() else None
